import itertools
import json

def solve():
    positions = [1, 2, 3, 4, 5]

    # Attributes and values as given in the puzzle
    names = ["Eric", "Peter", "Arnold", "Bob", "Alice"]
    styles = ["modern", "craftsman", "ranch", "victorian", "colonial"]
    mothers = ["Penny", "Kailyn", "Holly", "Janelle", "Aniya"]
    phones = ["oneplus 9", "google pixel 6", "huawei p50", "iphone 13", "samsung galaxy s21"]
    drinks = ["coffee", "water", "root beer", "tea", "milk"]
    animals = ["fish", "dog", "horse", "bird", "cat"]

    # Iterate over permutations applying constraints early to prune
    for name_perm in itertools.permutations(positions):
        name_pos = dict(zip(names, name_perm))
        # 9,17: Bob is the tea drinker in the fourth house -> Bob at 4
        if name_pos["Bob"] != 4:
            continue
        # 16: Eric is not in the second house
        if name_pos["Eric"] == 2:
            continue

        for mother_perm in itertools.permutations(positions):
            mother_pos = dict(zip(mothers, mother_perm))
            # 19: modern -> Penny (will set style later, but we know Penny's position from 18/12/19)
            # 18 + 12 + 19 together imply Penny is in position 3
            if mother_pos["Penny"] != 3:
                continue
            # 21: Aniya is not in the fourth house
            if mother_pos["Aniya"] == 4:
                continue
            # 22 + 2: Janelle is the one who only drinks water; Alice drinks water => Janelle at Alice's position
            if mother_pos["Janelle"] != name_pos["Alice"]:
                continue
            # 10: Tea drinker to the right of Kailyn; tea is in 4 => Kailyn < 4
            if not (mother_pos["Kailyn"] < 4):
                continue
            # 11 + 20: Root beer lover (Peter) is left of Kailyn
            if not (name_pos["Peter"] < mother_pos["Kailyn"]):
                continue

            for style_perm in itertools.permutations(positions):
                style_pos = dict(zip(styles, style_perm))
                # 12 + 18: Horses in third house and horses=modern => modern at 3
                if style_pos["modern"] != 3:
                    continue
                # 5: Ranch = Kailyn
                if style_pos["ranch"] != mother_pos["Kailyn"]:
                    continue
                # 7: Colonial is not in the fourth house
                if style_pos["colonial"] == 4:
                    continue

                for phone_perm in itertools.permutations(positions):
                    phone_pos = dict(zip(phones, phone_perm))
                    # 18 + 4: Horses in third house, horses=OnePlus 9 => OnePlus 9 at 3
                    if phone_pos["oneplus 9"] != 3:
                        continue
                    # 1: Google Pixel 6 is not in the first house
                    if phone_pos["google pixel 6"] == 1:
                        continue
                    # 15: Google Pixel 6 = Craftsman
                    if style_pos["craftsman"] != phone_pos["google pixel 6"]:
                        continue
                    # 3: Colonial is right of Huawei P50
                    if not (style_pos["colonial"] > phone_pos["huawei p50"]):
                        continue

                    for drink_perm in itertools.permutations(positions):
                        drink_pos = dict(zip(drinks, drink_perm))
                        # 17: Tea is in the fourth house
                        if drink_pos["tea"] != 4:
                            continue
                        # 9: Tea drinker is Bob
                        if drink_pos["tea"] != name_pos["Bob"]:
                            continue
                        # 2: Water is Alice
                        if drink_pos["water"] != name_pos["Alice"]:
                            continue
                        # 20: Root beer lover is Peter
                        if drink_pos["root beer"] != name_pos["Peter"]:
                            continue
                        # 10: Tea to the right of Kailyn
                        if not (drink_pos["tea"] > mother_pos["Kailyn"]):
                            continue
                        # 11: Root beer to the left of Kailyn
                        if not (drink_pos["root beer"] < mother_pos["Kailyn"]):
                            continue
                        # 13: iPhone 13 = Milk
                        if drink_pos["milk"] != phone_pos["iphone 13"]:
                            continue

                        for animal_perm in itertools.permutations(positions):
                            animal_pos = dict(zip(animals, animal_perm))
                            # 18: Horses in the third house
                            if animal_pos["horse"] != 3:
                                continue
                            # 8: Bird keeper is in the fourth house
                            if animal_pos["bird"] != 4:
                                continue
                            # 14: Dog owner likes milk
                            if animal_pos["dog"] != drink_pos["milk"]:
                                continue
                            # 6: Root beer lover = Cat lover
                            if animal_pos["cat"] != drink_pos["root beer"]:
                                continue
                            # 12: Horses = Modern (already aligned at 3, but check consistency)
                            if animal_pos["horse"] != style_pos["modern"]:
                                continue
                            # 4: Horses = OnePlus 9 (already aligned at 3, but check consistency)
                            if animal_pos["horse"] != phone_pos["oneplus 9"]:
                                continue

                            # Found a valid solution; build output
                            pos_to_name = {pos: nm for nm, pos in name_pos.items()}
                            pos_to_style = {pos: st for st, pos in style_pos.items()}
                            pos_to_mother = {pos: mo for mo, pos in mother_pos.items()}
                            pos_to_phone = {pos: ph for ph, pos in phone_pos.items()}
                            pos_to_drink = {pos: dr for dr, pos in drink_pos.items()}
                            pos_to_animal = {pos: an for an, pos in animal_pos.items()}

                            header = ["House", "name", "style of house", "mothers' names", "phone models", "favorite drink", "animals"]
                            rows = []
                            for pos in positions:
                                rows.append([
                                    str(pos),
                                    pos_to_name[pos],
                                    pos_to_style[pos],
                                    pos_to_mother[pos],
                                    pos_to_phone[pos],
                                    pos_to_drink[pos],
                                    pos_to_animal[pos]
                                ])

                            result = {
                                "solution": {
                                    "header": header,
                                    "rows": rows
                                }
                            }
                            print(json.dumps(result, indent=2))
                            return

if __name__ == "__main__":
    solve()
